import 'package:drift/drift.dart';
import '../app_database.dart';
@DriftAccessor()
class TaskDao extends DatabaseAccessor<AppDatabase> { TaskDao(AppDatabase db):super(db);
 Future<Task?> getTaskById(String id)=>(db.select(db.tasks)..where((t)=>t.id.equals(id))).getSingleOrNull(); Future<Task?> getTaskByNumber(String n)=>(db.select(db.tasks)..where((t)=>t.taskNumber.equals(n))).getSingleOrNull(); Future<List<Task>> getTasks()=>db.select(db.tasks).get(); Future<List<Task>> getTasksForUser(String id) async { final q=db.select(db.tasks).join([innerJoin(db.taskAssignments,db.taskAssignments.taskId.equalsExp(db.tasks.id))]);q.where(db.taskAssignments.userId.equals(id));return (await q.get()).map((r)=>r.readTable(db.tasks)).toList(); } Future<List<Task>> getTasksForTeam(String id)=>(db.select(db.tasks)..where((t)=>t.assignedTeamId.equals(id))).get(); Future<List<Task>> getTasksByBatch(String id)=>(db.select(db.tasks)..where((t)=>t.batchId.equals(id))).get(); Future<List<Task>> getSubtasks(String id)=>(db.select(db.tasks)..where((t)=>t.parentTaskId.equals(id))).get();
 Future<List<TaskAssignment>> getTaskAssignments(String id)=>(db.select(db.taskAssignments)..where((t)=>t.taskId.equals(id))).get(); Future<List<ChecklistItem>> getChecklistItems(String id)=>(db.select(db.checklistItems)..where((t)=>t.taskId.equals(id))).get(); Future<List<TaskComment>> getComments(String id)=>(db.select(db.taskComments)..where((t)=>t.taskId.equals(id)&t.isDeleted.equals(false))).get(); Future<List<TaskAttachment>> getAttachments(String id)=>(db.select(db.taskAttachments)..where((t)=>t.taskId.equals(id))).get(); Future<List<TaskBlocker>> getBlockers(String id)=>(db.select(db.taskBlockers)..where((t)=>t.taskId.equals(id))).get(); Future<List<DeadlineExtensionRequest>> getExtensionRequests(String id)=>(db.select(db.deadlineExtensionRequests)..where((t)=>t.taskId.equals(id))).get(); Future<List<TaskApproval>> getApprovals(String id)=>(db.select(db.taskApprovals)..where((t)=>t.taskId.equals(id))).get();
 Future<void> insertTask(TasksCompanion v)=>db.into(db.tasks).insert(v); Future<bool> updateTask(TasksCompanion v)=>db.update(db.tasks).replace(v); Future<void> insertAssignments(List<TaskAssignmentsCompanion> v)=>db.batch((b)=>b.insertAll(db.taskAssignments,v)); Future<void> insertChecklistItems(List<ChecklistItemsCompanion> v)=>db.batch((b)=>b.insertAll(db.checklistItems,v)); Future<void> insertComment(TaskCommentsCompanion v)=>db.into(db.taskComments).insert(v); Future<void> insertAttachmentMetadata(TaskAttachmentsCompanion v)=>db.into(db.taskAttachments).insert(v); Future<void> insertBlocker(TaskBlockersCompanion v)=>db.into(db.taskBlockers).insert(v); Future<void> insertExtensionRequest(DeadlineExtensionRequestsCompanion v)=>db.into(db.deadlineExtensionRequests).insert(v); Future<void> insertApproval(TaskApprovalsCompanion v)=>db.into(db.taskApprovals).insert(v);
}
